TO_LN = "https://www.timeoutdoha.com/food-drink/ladies-nights-doha-deals"

D = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
def days(*names):
    return [d for d in D if d in names]
DAILY = D
def but(*x):
    return [d for d in D if d not in x]
SUN_THU = days("sun", "mon", "tue", "wed", "thu")
SUN_WED = days("sun", "mon", "tue", "wed")
MON_SAT = but("sun")
