# Arabic short phrases (the Arabic app shows these)
def ar_from(p): return f"مشروبات مختارة ابتداءً من {p} ر.ق"
def ar_pct(p, what="المشروبات المختارة"): return f"خصم {p}٪ على {what}"
AR_SPECIAL = "أسعار خاصة على المشروبات المختارة"
def ar_unl(h, p): return f"مشروبات مختارة بلا حدود لمدة {h} مقابل {p} ر.ق"
def ar_pkg(p): return f"باقة مشروبات ولقمات مقابل {p} ر.ق"
AR_LADIES_FREE = "مشروبات مجانية للسيدات"
def ar_ladies(p): return f"عرض السيدات مقابل {p} ر.ق"
def ar_staff(p, who): return f"خصم {p}٪ لـ{who} مع إثبات الهوية"
